draw:
var L = p.L, g = p.g;
var T = 2 * Math.PI * Math.sqrt(L / g);
var th0 = 0.30;
var th = th0 * Math.cos(2 * Math.PI * t / T);

var pad = 20;
var px = W * 0.5;
var py = pad + 8;
var Lmax = 4.2;
var pixPerM = (H - pad * 2 - 26) / Lmax;
var len = L * pixPerM;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
ctx.lineWidth = 1;

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(px - 46, py); ctx.lineTo(px + 46, py); ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, py + len + 16); ctx.stroke();
ctx.setLineDash([]);

var bx = px + len * Math.sin(th);
var by = py + len * Math.cos(th);

ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(bx, by); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(bx, by, 8, 0, Math.PI * 2); ctx.fill();

ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(bx, by + 10); ctx.lineTo(bx, by + 10 + g * 1.6); ctx.stroke();
ctx.beginPath();
ctx.moveTo(bx, by + 14 + g * 1.6);
ctx.lineTo(bx - 4, by + 8 + g * 1.6);
ctx.lineTo(bx + 4, by + 8 + g * 1.6);
ctx.closePath(); ctx.fill();
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("g", bx + 7, by + 14 + g * 0.8);

ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(px - 26, py); ctx.lineTo(px - 26, py + len);
ctx.moveTo(px - 30, py); ctx.lineTo(px - 22, py);
ctx.moveTo(px - 30, py + len); ctx.lineTo(px - 22, py + len);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "right";
ctx.fillText("L = " + L.toFixed(2) + " m", px - 34, py + len / 2);

var gw = W - 30;
var y0 = H - 14;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(14, y0); ctx.lineTo(14 + gw, y0); ctx.stroke();
var frac = (t % T) / T;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(14, y0); ctx.lineTo(14 + gw * frac, y0); ctx.stroke();
ctx.lineWidth = 1;
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("one period", 14, y0 - 12);
ctx.textAlign = "right";
ctx.fillText(T.toFixed(2) + " s", 14 + gw, y0 - 12);

out.note = "T = 2*pi*sqrt(L/g) = 2*pi*sqrt(" + L.toFixed(2) + "/" + g.toFixed(1) +
  ") = " + T.toFixed(2) + " s   (quadruple L and T only doubles)";
